<template><main class="hh-page counter-documents"><router-link to="/contrareferencias" class="hh-back-link d-inline-flex align-items-center mb-3"><i class="ph ph-arrow-left me-1"></i>Volver a contrarreferencias</router-link><section class="docs-hero"><div><span>SOPORTES DE EGRESO</span><h1>Documentos de contrarreferencia</h1><p>Adjunte y consulte los documentos entregados para la continuidad asistencial.</p></div><i class="ph ph-files"></i></section><div v-if="notice.text" class="alert mt-3" :class="`alert-${notice.type}`">{{notice.text}}</div><section class="upload-card mt-4"><header><span><i class="ph ph-upload-simple"></i></span><div><small>NUEVO DOCUMENTO</small><h2>Adjuntar soporte</h2></div></header><form class="row g-3" @submit.prevent="upload"><div class="col-md-5"><label class="form-label">Archivo *</label><input ref="fileInput" type="file" class="form-control" accept=".pdf,image/*" required @change="file=$event.target.files[0]"><small v-if="file" class="text-muted">{{file.name}} · {{size(file.size)}}</small></div><div class="col-md-3"><label class="form-label">Tipo documental *</label><select v-model="typeId" class="form-select" required><option value="" disabled>Seleccione</option><option v-for="item in types" :key="id(item)" :value="id(item)">{{name(item)}}</option></select></div><div class="col-md-4"><label class="form-label">Descripción</label><input v-model.trim="description" maxlength="500" class="form-control"></div><div class="col-12 d-flex justify-content-end"><button class="btn btn-primary" :disabled="saving||!file"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span><i v-else class="ph ph-upload-simple me-1"></i>Adjuntar documento</button></div></form></section><section class="documents-card mt-4"><header><div><small>ARCHIVOS ASOCIADOS</small><h2>Documentos adjuntos</h2></div><span>{{documents.length}}</span></header><div v-if="loading" class="text-center py-5"><span class="spinner-border text-primary"></span></div><div v-else-if="!documents.length" class="empty"><i class="ph ph-file-dashed"></i><h3>Sin documentos</h3><p>Esta contrarreferencia todavía no tiene soportes adjuntos.</p></div><div v-else class="document-grid"><article v-for="item in documents" :key="item.id"><span><i class="ph ph-file-pdf"></i></span><div><small>{{item.tipo_documento?.nombre||'DOCUMENTO'}}</small><strong>{{item.nombre_archivo||item.nombre||`Documento #${item.id}`}}</strong><p>{{item.descripcion||'Sin descripción'}}</p></div><button class="btn btn-sm btn-outline-danger" @click="askDelete=item"><i class="ph ph-trash"></i></button></article></div></section><Teleport to="body"><div v-if="askDelete" class="confirm-layer" @mousedown.self="askDelete=null"><section><span><i class="ph ph-trash"></i></span><h3>¿Eliminar documento?</h3><p>El soporte <strong>{{askDelete.nombre_archivo||askDelete.nombre}}</strong> será retirado de la contrarreferencia.</p><div><button class="btn btn-outline-secondary" :disabled="saving" @click="askDelete=null">Cancelar</button><button class="btn btn-danger" :disabled="saving" @click="remove"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>Eliminar</button></div></section></div></Teleport></main></template>
<script setup>import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{adjuntarDocumentoContrareferencia,consultarCatalogosReferencia,eliminarDocumentoContrareferencia,listarDocumentosContrareferencia}from'@/services/referencias';const route=useRoute(),counterId=Number(route.params.id),documents=ref([]),types=ref([]),origins=ref([]),loading=ref(false),saving=ref(false),file=ref(null),fileInput=ref(null),typeId=ref(''),description=ref(''),askDelete=ref(null),notice=ref({text:'',type:'success'}),array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[],id=x=>x.id??x.tipo_documento_id??x.origen_id,name=x=>x.nombre??x.name??x.descripcion,size=b=>b<1048576?`${(b/1024).toFixed(1)} KB`:`${(b/1048576).toFixed(1)} MB`;async function load(){loading.value=true;try{documents.value=array(await listarDocumentosContrareferencia(counterId))}catch(e){showError(e)}finally{loading.value=false}}async function upload(){if(!file.value)return;if(file.value.size>10*1024*1024){notice.value={text:'El archivo supera el máximo permitido de 10 MB.',type:'danger'};return}const origin=origins.value.find(x=>String(x.codigo||name(x)).toUpperCase().includes('CONTRARREFERENCIA'));if(!origin){notice.value={text:'No se encontró el origen documental CONTRARREFERENCIA.',type:'danger'};return}saving.value=true;try{const data=new FormData();data.append('archivo',file.value);data.append('tipo_documento_id',typeId.value);data.append('origen_id',id(origin));if(description.value)data.append('descripcion',description.value);await adjuntarDocumentoContrareferencia(counterId,data);file.value=null;typeId.value='';description.value='';if(fileInput.value)fileInput.value.value='';notice.value={text:'Documento adjuntado correctamente.',type:'success'};await load()}catch(e){showError(e)}finally{saving.value=false}}async function remove(){saving.value=true;try{await eliminarDocumentoContrareferencia(counterId,askDelete.value.id);askDelete.value=null;notice.value={text:'Documento eliminado correctamente.',type:'success'};await load()}catch(e){showError(e)}finally{saving.value=false}}function showError(e){notice.value={text:obtenerMensajeError(e),type:'danger'}}onMounted(async()=>{const c=await consultarCatalogosReferencia().catch(()=>null),s=c?.data||c||{};types.value=s.tipos_documento||s.tipos_documentos||[];origins.value=s.origenes_documento||s.origenes_documentos||[];await load()})</script>
<style scoped>.docs-hero{display:flex;align-items:center;justify-content:space-between;padding:1.4rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#0b5587,#148fbc);color:#fff}.docs-hero span,.upload-card header small,.documents-card header small{font-size:.6rem;font-weight:800;letter-spacing:.08em}.docs-hero h1{margin:.2rem 0;font-size:1.5rem}.docs-hero p{margin:0;opacity:.82}.docs-hero>i{font-size:2.5rem;opacity:.35}.upload-card,.documents-card{overflow:hidden;border:1px solid #dfe7ee;border-radius:1rem;background:#fff;box-shadow:0 9px 28px rgba(25,63,95,.06)}.upload-card>header,.documents-card>header{display:flex;align-items:center;gap:.65rem;padding:1rem 1.2rem;border-bottom:1px solid #e3e9ef;background:#fbfcfe}.upload-card header>span{display:grid;place-items:center;width:39px;height:39px;border-radius:11px;background:#e8f4fc;color:var(--bs-primary);font-size:1.1rem}.upload-card h2,.documents-card h2{margin:.1rem 0;font-size:1.02rem}.upload-card form{padding:1.2rem}.documents-card>header{justify-content:space-between}.documents-card>header>span{display:grid;place-items:center;min-width:30px;height:30px;border-radius:9px;background:#e8f3fb;color:var(--bs-primary);font-size:.68rem;font-weight:800}.document-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.7rem;padding:1rem}.document-grid article{display:flex;align-items:center;gap:.65rem;padding:.75rem;border:1px solid #e1e8ee;border-radius:.7rem}.document-grid article>span{display:grid;place-items:center;width:39px;height:39px;border-radius:11px;background:#fff0f1;color:#c64651;font-size:1.15rem}.document-grid article>div{min-width:0;flex:1}.document-grid small,.document-grid strong{display:block}.document-grid small{color:#8290a0;font-size:.56rem}.document-grid strong{overflow:hidden;font-size:.72rem;text-overflow:ellipsis;white-space:nowrap}.document-grid p{margin:.1rem 0 0;color:#758496;font-size:.62rem}.empty{text-align:center;padding:4rem;color:#718096}.empty i{font-size:2.8rem;color:#abc1d0}.empty h3{margin:.6rem 0 .2rem;font-size:1rem}.confirm-layer{position:fixed;inset:0;z-index:2100;display:grid;place-items:center;padding:1rem;background:#071522b8;backdrop-filter:blur(5px)}.confirm-layer section{width:min(430px,100%);padding:1.5rem;border-radius:1rem;background:#fff;text-align:center}.confirm-layer section>span{display:grid;place-items:center;width:52px;height:52px;margin:0 auto .8rem;border-radius:15px;background:#fff0f1;color:#c53f4a;font-size:1.35rem}.confirm-layer h3{font-size:1.05rem}.confirm-layer p{color:#687789;font-size:.72rem}.confirm-layer section>div{display:flex;justify-content:center;gap:.6rem;margin-top:1rem}@media(max-width:700px){.document-grid{grid-template-columns:1fr}}</style>
